insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery) values ('nijigasaki-sweet-collection-2027','nijigasaki-sweet-collection-2027','ムービックより 映画『ラブライブ！虹ヶ咲学園スクールアイドル同好会 完結編 最終章』公開記念 Sweet Collectionフェア 開催と描き下ろし新商品のお知らせ','虹咲完结篇 Sweet Collection 新绘商品与特典','其他联动','配合电影最终章的 Sweet Collection 主题商品活动。这里列出已有地址资料的部分参加门店，完整店铺名单及通販请查官方公告。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/15/1002/470nuEz0SPtb03Jp/4764ruDfBlx9tZmR.jpeg","alt":"虹咲完结篇 Sweet Collection 新绘商品与特典 · 官方公告图","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6700","checked_on":"2026-10-28"}',null,'["参加商品购买或预约可获 13 款生写真特典；金额、随机方式和适用预约付款条件须按各店规则确认。","已公告商品：立牌、文件夹、桌垫、方形徽章、极光艺术卡和糖果造型钥匙扣。单品精确发售日与价格尚未逐一核实。","仅列官网明确参加范围内的已知分店，非全国完整目录；不含 Animate 三宫。","活动期间并不代表现在已开放所有商品预约，也不代表现场有货。"]','published','2026-10-28T12:00:00+09:00','2026-10-28T12:00:00+09:00','[{"id":"niji-sweet-bromide","title":"购买 / 预约特典：生写真（13 款）","rule":"指定商品购买或预约可获生写真；此公告未列各店金额门槛、选款及合票规则，需到对应店铺详情核实。","threshold_yen":null,"threshold_quantity":null,"channel":"门店及通販","scope":"公告所列 Animate 门店及通販、Gamers 门店及通販、Movic 通販；各渠道条件单独确认","venue_ids":[],"starts_on":"2027-01-30","ends_on":"2027-02-28","selection":"未说明","receipt_combination":"未说明","while_supplies_last":null,"image":{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/15/1002/470nuEz0SPtb03Jp/4764ruDfBlx9tZmR.jpeg","alt":"Sweet Collection 商品与特典公告","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6700","checked_on":"2026-10-28"},"source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6700","checked_on":"2026-10-28"}]','[]') on conflict do nothing;
